"""Regenerate src/hyphen_builtin_data.h from data/hyph-en-us.pat.txt (python -I tools/gen_hyphen_builtin.py)."""
from pathlib import Path
root = Path(__file__).resolve().parents[1]
data = (root / 'data' / 'hyph-en-us.pat.txt').read_bytes()
rows = []
for i in range(0, len(data), 24):
    rows.append('  ' + ','.join(str(b) for b in data[i:i + 24]))
(root / 'src' / 'hyphen_builtin_data.h').write_text(
    '/* SPDX-License-Identifier: MIT */\n'
    '/* Generated by tools/gen_hyphen_builtin.py from data/hyph-en-us.pat.txt; see data/hyph-en-us.LICENSE.txt. */\n'
    'static const unsigned char exr_hyphen_en_us_patterns[] = {\n' + ',\n'.join(rows) + '\n};\n', newline='\n')
